mapper.select:

SELECT
    /* 어제까지 전체 = (어제까지 제출) + (어제까지 예정) */
    (
        (SELECT COUNT(*)
         FROM inspections i
                  JOIN facilities f ON f.facility_id = i.facility_id
         WHERE TRUNC(i.submitted_at) < TRUNC(SYSDATE)
           AND f.managers_id = #{managerId})
            +
        (SELECT COUNT(*)
         FROM facilities f
         WHERE TRUNC(f.next_scheduled_at) < TRUNC(SYSDATE)
           AND f.managers_id = #{managerId})
        ) AS untilYesterdayTotal,

    /* 어제까지 완료 = 어제까지 제출 */
    (SELECT COUNT(*)
     FROM inspections i
              JOIN facilities f ON f.facility_id = i.facility_id
     WHERE TRUNC(i.submitted_at) < TRUNC(SYSDATE)
       AND f.managers_id = #{managerId}
    ) AS untilYesterdayCompleted,

    /* 오늘 이후 예정 */
    (SELECT COUNT(*)
     FROM facilities f
     WHERE TRUNC(f.next_scheduled_at) > TRUNC(SYSDATE)
       AND f.managers_id = #{managerId}
    ) AS upcomingCount,

    /* 미점검 현황: 어제까지 예정 설비 수 (요청대로 간단 카운트) */
    (SELECT COUNT(*)
     FROM facilities f
     WHERE f.next_scheduled_at < TRUNC(SYSDATE)
       AND f.managers_id = #{managerId}
    ) AS overdueUninspected
FROM dual
